package mcpclient

import (
	"context"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"testing"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/propagation"
	sdkmetric "go.opentelemetry.io/otel/sdk/metric"

	"github.com/openai/tunnel-client/pkg/runtimeconfig"
)

func TestLocalTracingDoesNotInjectGlobalHTTPContext(t *testing.T) {
	original := otel.GetTextMapPropagator()
	if len(original.Fields()) == 0 {
		original = propagation.NewCompositeTextMapPropagator()
	}
	otel.SetTextMapPropagator(propagation.NewCompositeTextMapPropagator(propagation.TraceContext{}, propagation.Baggage{}))
	t.Cleanup(func() { otel.SetTextMapPropagator(original) })
	headers := make(chan http.Header, 1)
	server := httptest.NewServer(http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		headers <- request.Header.Clone()
		writer.WriteHeader(http.StatusNoContent)
	}))
	t.Cleanup(server.Close)
	for _, enabled := range []bool{false, true} {
		transport, err := buildMcpHTTPTransport(slog.New(slog.NewTextHandler(io.Discard, nil)), &runtimeconfig.LoggingConfig{}, sdkmetric.NewMeterProvider(), nil, nil, "", nil, mustParseURL(t, server.URL), nil, nil, enabled)
		if err != nil {
			t.Fatal(err)
		}
		ctx := otel.GetTextMapPropagator().Extract(context.Background(), propagation.MapCarrier{
			"traceparent": "00-1234567890abcdef1234567890abcdef-1234567890abcdef-01",
			"tracestate":  "private=secret", "baggage": "private=prompt",
		})
		request, err := http.NewRequestWithContext(ctx, http.MethodGet, server.URL, nil)
		if err != nil {
			t.Fatal(err)
		}
		response, err := transport.RoundTrip(request)
		if err != nil {
			t.Fatal(err)
		}
		_ = response.Body.Close()
		observed := <-headers
		for _, name := range []string{"traceparent", "tracestate", "baggage"} {
			if (observed.Get(name) == "") != enabled {
				t.Fatalf("enabled=%v unexpected %s header: %q", enabled, name, observed.Get(name))
			}
		}
		if enabled {
			request.Header.Set("traceparent", "caller-owned")
			response, err := transport.RoundTrip(request)
			if err != nil {
				t.Fatal(err)
			}
			_ = response.Body.Close()
			if (<-headers).Get("traceparent") != "caller-owned" {
				t.Fatal("caller-owned header changed")
			}
		}
	}
}

package oauth

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"net/url"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/jpillora/backoff"
	"go.uber.org/fx"

	"github.com/openai/tunnel-client/pkg/runtimeconfig"
	"github.com/openai/tunnel-client/pkg/runtimeharpoon/hostbus"
)

func TestOAuthDiscoveryRetriesAfterTransientTimeout(t *testing.T) {
	t.Parallel()

	var recovered atomic.Bool
	enteredRetry := make(chan time.Duration, 1)
	allowRetry := make(chan struct{})
	httpClient := &http.Client{Transport: roundTripFunc(func(req *http.Request) (*http.Response, error) {
		if !recovered.Load() {
			return nil, context.DeadlineExceeded
		}

		statusCode := http.StatusNotFound
		body := ""
		if req.URL.Path == "/.well-known/oauth-protected-resource" {
			statusCode = http.StatusOK
			body = `{"resource":"https://mcp.example.test/mcp"}`
		}
		return &http.Response{
			StatusCode: statusCode,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader(body)),
			Request:    req,
		}, nil
	})}
	state := startOAuthDiscoveryTestApp(
		t,
		httpClient,
		deterministicOAuthDiscoveryRetryPolicy(enteredRetry, allowRetry),
	)

	var retryDelay time.Duration
	select {
	case retryDelay = <-enteredRetry:
	case <-time.After(time.Second):
		t.Fatal("OAuth discovery did not enter retry after its timeout cycle")
	}
	if retryDelay <= 0 {
		t.Fatalf("retry delay = %s, want a positive delay", retryDelay)
	}
	if state.IsDone() {
		t.Fatal("transient timeout finalized discovery instead of leaving it pending for retry")
	}

	recovered.Store(true)
	close(allowRetry)

	result, _, _, err, ok := state.Wait(time.Second)
	if !ok {
		t.Fatal("OAuth discovery did not finish after the transport recovered")
	}
	if err != nil {
		t.Fatalf("OAuth discovery remained failed after the transport recovered: %v", err)
	}
	if result == nil || result.URL != "https://mcp.example.test/.well-known/oauth-protected-resource" {
		t.Fatalf("unexpected discovery result after recovery: %#v", result)
	}
}

func TestOAuthDiscoveryRetriesAfterTransientMetadataBodyTimeout(t *testing.T) {
	t.Parallel()

	var recovered atomic.Bool
	enteredRetry := make(chan time.Duration, 1)
	allowRetry := make(chan struct{})
	httpClient := &http.Client{Transport: roundTripFunc(func(req *http.Request) (*http.Response, error) {
		if req.URL.Path == "/mcp" {
			return &http.Response{
				StatusCode: http.StatusNotFound,
				Header:     make(http.Header),
				Body:       io.NopCloser(strings.NewReader("")),
				Request:    req,
			}, nil
		}
		if !recovered.Load() {
			return &http.Response{
				StatusCode: http.StatusOK,
				Header:     make(http.Header),
				Body:       io.NopCloser(&errorReader{err: context.DeadlineExceeded}),
				Request:    req,
			}, nil
		}

		statusCode := http.StatusNotFound
		body := ""
		if req.URL.Path == "/.well-known/oauth-protected-resource" {
			statusCode = http.StatusOK
			body = `{"resource":"https://mcp.example.test/mcp"}`
		}
		return &http.Response{
			StatusCode: statusCode,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader(body)),
			Request:    req,
		}, nil
	})}
	state := startOAuthDiscoveryTestApp(
		t,
		httpClient,
		deterministicOAuthDiscoveryRetryPolicy(enteredRetry, allowRetry),
	)

	select {
	case <-enteredRetry:
	case <-time.After(time.Second):
		t.Fatal("OAuth discovery did not retry after its metadata body timed out")
	}
	if state.IsDone() {
		t.Fatal("metadata body timeout finalized discovery instead of leaving it pending for retry")
	}

	recovered.Store(true)
	close(allowRetry)

	result, _, _, err, ok := state.Wait(time.Second)
	if !ok {
		t.Fatal("OAuth discovery did not finish after metadata body reads recovered")
	}
	if err != nil {
		t.Fatalf("OAuth discovery remained failed after metadata body reads recovered: %v", err)
	}
	if result == nil || result.URL != "https://mcp.example.test/.well-known/oauth-protected-resource" {
		t.Fatalf("unexpected discovery result after metadata body recovery: %#v", result)
	}
}

func TestOAuthDiscoveryPreservesFailFastForNonTimeoutFailure(t *testing.T) {
	t.Parallel()

	transportErr := errors.New("dial failed")
	state := startOAuthDiscoveryTestApp(t, &http.Client{Transport: roundTripFunc(func(*http.Request) (*http.Response, error) {
		return nil, transportErr
	})})

	_, _, _, err, ok := state.Wait(time.Second)
	if !ok {
		t.Fatal("non-timeout OAuth discovery failure did not finish promptly")
	}
	if !errors.Is(err, transportErr) {
		t.Fatalf("OAuth discovery error = %v, want wrapped transport error", err)
	}
}

func TestOAuthDiscoveryPreservesFailFastForMixedFailureCycle(t *testing.T) {
	t.Parallel()

	permanentErr := errors.New("permanent transport failure")
	enteredRetry := make(chan time.Duration, 1)
	httpClient := &http.Client{Transport: roundTripFunc(func(req *http.Request) (*http.Response, error) {
		switch req.URL.Path {
		case "/mcp":
			return &http.Response{
				StatusCode: http.StatusNotFound,
				Header:     make(http.Header),
				Body:       io.NopCloser(strings.NewReader("")),
				Request:    req,
			}, nil
		case "/.well-known/oauth-protected-resource/mcp":
			return nil, permanentErr
		case "/.well-known/oauth-protected-resource":
			return nil, context.DeadlineExceeded
		default:
			t.Fatalf("unexpected request path: %s", req.URL.Path)
			return nil, permanentErr
		}
	})}
	state := startOAuthDiscoveryTestApp(t, httpClient, oauthDiscoveryRetryPolicy{
		newBackoff: deterministicOAuthDiscoveryBackoff,
		wait: func(ctx context.Context, delay time.Duration) bool {
			select {
			case enteredRetry <- delay:
			case <-ctx.Done():
			}
			return false
		},
	})

	_, _, _, err, ok := state.Wait(time.Second)
	if !ok {
		select {
		case <-enteredRetry:
			t.Fatal("mixed timeout/non-timeout discovery cycle retried instead of failing fast")
		default:
		}
		t.Fatal("mixed failure cycle did not finish promptly")
	}
	if err == nil {
		t.Fatal("mixed failure cycle completed without an error")
	}
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("discovery error = %v, want the original final timeout", err)
	}
	select {
	case <-enteredRetry:
		t.Fatal("mixed timeout/non-timeout discovery cycle retried instead of failing fast")
	default:
	}
}

func TestWaitForOAuthDiscoveryRetryStopsWhenContextIsCanceled(t *testing.T) {
	t.Parallel()

	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	if waitForOAuthDiscoveryRetry(ctx, time.Hour) {
		t.Fatal("retry wait completed after its context was canceled")
	}
}

func deterministicOAuthDiscoveryRetryPolicy(
	enteredRetry chan<- time.Duration,
	allowRetry <-chan struct{},
) oauthDiscoveryRetryPolicy {
	return oauthDiscoveryRetryPolicy{
		newBackoff: deterministicOAuthDiscoveryBackoff,
		wait: func(ctx context.Context, delay time.Duration) bool {
			select {
			case enteredRetry <- delay:
			case <-ctx.Done():
				return false
			}
			select {
			case <-allowRetry:
				return true
			case <-ctx.Done():
				return false
			}
		},
	}
}

func deterministicOAuthDiscoveryBackoff() *backoff.Backoff {
	return &backoff.Backoff{
		Min:    time.Second,
		Max:    time.Second,
		Factor: 1,
		Jitter: false,
	}
}

func startOAuthDiscoveryTestApp(
	t *testing.T,
	httpClient *http.Client,
	retryPolicies ...oauthDiscoveryRetryPolicy,
) *DiscoveryState {
	t.Helper()

	serverURL, err := url.Parse("https://mcp.example.test/mcp")
	if err != nil {
		t.Fatalf("parse server url: %v", err)
	}
	state := NewDiscoveryState()
	bus := &recordingBus{notify: make(chan struct{})}
	invoke := any(startOAuthDiscovery)
	if len(retryPolicies) > 0 {
		retryPolicy := retryPolicies[0]
		invoke = func(p discoveryParams) error {
			return startOAuthDiscoveryWithRetryPolicy(p, retryPolicy)
		}
	}
	app := fx.New(
		fx.NopLogger,
		fx.Provide(
			func() *runtimeconfig.MCPConfig {
				return &runtimeconfig.MCPConfig{
					ServerURL:     serverURL,
					TransportKind: runtimeconfig.MCPTransportHTTPStreamable,
				}
			},
			fx.Annotate(
				func() *http.Client { return httpClient },
				fx.ResultTags(`name:"mcp_client"`),
			),
			func() hostbus.HostRegistrationBus { return bus },
			func() *slog.Logger { return slog.New(slog.NewTextHandler(io.Discard, nil)) },
			func() *DiscoveryState { return state },
		),
		fx.Invoke(invoke),
	)
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	if err := app.Start(ctx); err != nil {
		cancel()
		t.Fatalf("start: %v", err)
	}
	t.Cleanup(func() {
		cancel()
		_ = app.Stop(context.Background())
	})
	return state
}

package mockmcpserver

import (
	"flag"
	"fmt"
	"os"
	"strconv"
	"testing"
)

// TestMain caps test.parallel so at most two tests run concurrently in this package.
func TestMain(m *testing.M) {
	const maxParallel = 2

	if f := flag.Lookup("test.parallel"); f != nil {
		if cur, err := strconv.Atoi(f.Value.String()); err != nil || cur > maxParallel {
			_ = f.Value.Set(strconv.Itoa(maxParallel))
		}
		fmt.Fprintf(os.Stderr, "mockmcpserver: test.parallel=%s\n", f.Value.String())
	}

	os.Exit(m.Run())
}

package mockmcpserver

import (
	"encoding/json"
	"fmt"
	"net/http"
)

// Package mockmcpserver provides MCP server doubles that let tests script tool
// responses and capture incoming call metadata without standing up a real MCP
// server. Use Start to run a streamable HTTP server, or StartInMemory/StartStdio
// to run over in-memory or stdio transports.
//
// Configure the server entirely through options such as WithCalls, start it in
// a test with testing.TB, and exercise it with a real MCP client.

// ExampleNewMockMCPServer_withCalls shows how to queue scripted tool calls when
// constructing the mock server.
func ExampleNewMockMCPServer_withCalls() {
	server := NewMockMCPServer(
		WithCalls(
			Call{
				Tool:   "ping",
				Result: json.RawMessage(`{"message":"pong"}`),
				ResponseHeaders: http.Header{
					"X-Mcp-Mode": {"simple"},
				},
			},
			Call{
				Tool: "stream",
				Progress: []ProgressUpdate{
					{Percentage: 50, Message: "halfway"},
				},
				Result: json.RawMessage(`{"complete":true}`),
				ResponseHeaders: http.Header{
					"X-Mcp-Mode": {"stream"},
				},
			},
		),
	)

	_ = server // In tests, call server.Start(t) and point your MCP client at server.BaseURL().
}

// ExampleMockMCPServer_receivedRequests demonstrates inspecting the recorded
// tool invocations after the client finishes calling the MCP server.
func ExampleMockMCPServer_receivedRequests() {
	server := NewMockMCPServer(
		WithCalls(
			Call{
				Tool:   "ping",
				Result: json.RawMessage(`{"message":"pong"}`),
			},
		),
	)

	for _, req := range server.ReceivedRequests() {
		fmt.Printf("%s -> %s\n", req.Tool, string(req.Arguments))
	}
}

package mockmcpserver

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/modelcontextprotocol/go-sdk/oauthex"
)

func TestMockMCPServerUsage(t *testing.T) {
	t.Parallel()

	server := NewMockMCPServer(
		WithCalls(
			Call{
				Tool:   "ping",
				Result: json.RawMessage(`{"message":"pong"}`),
				ResponseHeaders: http.Header{
					"X-Mcp-Mode": {"simple"},
				},
			},
			Call{
				Tool: "stream",
				Progress: []ProgressUpdate{
					{Percentage: 50, Message: "halfway"},
				},
				Result: json.RawMessage(`{"complete":true}`),
				ResponseHeaders: http.Header{
					"X-Mcp-Mode": {"stream"},
				},
			},
		),
	)
	server.Start(t)

	baseURL := server.BaseURL()
	if baseURL == nil {
		t.Fatal("mock MCP server did not expose a base URL")
	}

	var (
		progressMu sync.Mutex
		progress   []float64
		progressCh = make(chan struct{}, 1)
	)
	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "0.1"}, &mcp.ClientOptions{
		ProgressNotificationHandler: func(_ context.Context, req *mcp.ProgressNotificationClientRequest) {
			progressMu.Lock()
			progress = append(progress, req.Params.Progress)
			if len(progress) == 1 {
				select {
				case progressCh <- struct{}{}:
				default:
				}
			}
			progressMu.Unlock()
		},
	})

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	session, err := client.Connect(ctx, &mcp.StreamableClientTransport{
		Endpoint:   baseURL.String(),
		HTTPClient: httpClientForServer(t, server),
	}, nil)
	if err != nil {
		t.Fatalf("connect MCP client: %v", err)
	}
	defer func() {
		_ = session.Close()
	}()

	pingRes, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "ping"})
	if err != nil {
		t.Fatalf("call ping: %v", err)
	}
	var pingStructured map[string]any
	rawPing, err := json.Marshal(pingRes.StructuredContent)
	if err == nil {
		_ = json.Unmarshal(rawPing, &pingStructured)
	}
	if pingStructured["message"] != "pong" {
		t.Fatalf("unexpected ping result: %v", pingStructured)
	}

	progressMu.Lock()
	progress = progress[:0]
	progressMu.Unlock()

	streamParams := &mcp.CallToolParams{Name: "stream", Arguments: map[string]any{"topic": "demo"}}
	streamParams.SetProgressToken("stream-progress")
	streamRes, err := session.CallTool(ctx, streamParams)
	if err != nil {
		t.Fatalf("call stream: %v", err)
	}
	var streamStructured map[string]any
	if raw, err := json.Marshal(streamRes.StructuredContent); err == nil {
		_ = json.Unmarshal(raw, &streamStructured)
	}
	if streamStructured["complete"] != true {
		t.Fatalf("unexpected stream result: %v", streamStructured)
	}
	select {
	case <-progressCh:
	case <-time.After(time.Second):
		progressMu.Lock()
		defer progressMu.Unlock()
		t.Fatalf("expected progress notification, got %v", progress)
	}
	progressMu.Lock()
	firstProgress := progress[0]
	progressMu.Unlock()
	if firstProgress != 50 {
		t.Fatalf("unexpected progress updates: %v", progress)
	}

	waitCtx, waitCancel := context.WithTimeout(context.Background(), time.Second)
	defer waitCancel()
	if err := server.WaitForRequests(waitCtx, 2); err != nil {
		t.Fatalf("wait for requests: %v", err)
	}
	reqs := server.ReceivedRequests()
	if len(reqs) != 2 {
		t.Fatalf("expected 2 recorded requests, got %d", len(reqs))
	}
	if reqs[0].Tool != "ping" || reqs[1].Tool != "stream" {
		t.Fatalf("unexpected request order: %+v", reqs)
	}
}

func TestMockMCPServerCloseTerminatesActiveStreamableConnection(t *testing.T) {
	t.Parallel()

	server := NewMockMCPServer()
	server.Start(t)

	baseURL := server.BaseURL()
	if baseURL == nil {
		t.Fatal("mock MCP server did not expose a base URL")
	}

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "0.1"}, nil)
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()

	session, err := client.Connect(ctx, &mcp.StreamableClientTransport{
		Endpoint:   baseURL.String(),
		HTTPClient: httpClientForServer(t, server),
	}, nil)
	if err != nil {
		t.Fatalf("connect MCP client: %v", err)
	}
	defer func() {
		_ = session.Close()
	}()

	closed := make(chan struct{})
	go func() {
		server.Close()
		close(closed)
	}()

	select {
	case <-closed:
	case <-time.After(time.Second):
		_ = session.Close()
		select {
		case <-closed:
		case <-time.After(time.Second):
		}
		t.Fatal("mock MCP server Close blocked with an active streamable connection")
	}
}

