from __future__ import annotations

from pathlib import Path


def has_cmd_client_segments(path: Path) -> bool:
    return ("cmd", "client") in zip(path.parts, path.parts[1:])


def find_bazel_client_binaries(root: Path) -> list[Path]:
    bazel_bin = root / "bazel-bin"
    if not bazel_bin.is_dir():
        return []
    candidates = [*bazel_bin.rglob("client"), *bazel_bin.rglob("client.exe")]
    return [
        candidate
        for candidate in sorted(candidates)
        if has_cmd_client_segments(candidate.relative_to(bazel_bin))
    ]

from __future__ import annotations

import argparse
import os
import sys
from pathlib import Path

from tunnel_mcp_installer.core import DEFAULT_MARKETPLACE, install_plugin
from tunnel_mcp_installer.manifest import validate_plugin_segment


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Install this local Codex plugin into the plugin cache."
    )
    parser.add_argument(
        "--source",
        help="Path to the source plugin directory. Default: plugin containing this script.",
    )
    parser.add_argument(
        "--marketplace",
        default=DEFAULT_MARKETPLACE,
        help=f"Marketplace name used in cache paths. Default: {DEFAULT_MARKETPLACE}",
    )
    parser.add_argument(
        "--codex-home",
        help="Override CODEX_HOME. Default: $CODEX_HOME, then ~/.codex.",
    )
    parser.add_argument(
        "--tunnel-client-bin",
        help="Path to the tunnel-client binary persisted into the installed bundle.",
    )
    return parser.parse_args()


def default_source() -> Path:
    return Path(__file__).resolve().parents[2]


def resolve_codex_home(arg_value: str | None) -> Path:
    if arg_value:
        return Path(arg_value).expanduser().resolve()
    env_value = os.environ.get("CODEX_HOME")
    if env_value:
        return Path(env_value).expanduser().resolve()
    return (Path.home() / ".codex").resolve()


def main() -> int:
    args = parse_args()
    source = Path(args.source).expanduser().resolve() if args.source else default_source()
    codex_home = resolve_codex_home(args.codex_home)
    marketplace = validate_plugin_segment(
        args.marketplace.strip() or DEFAULT_MARKETPLACE,
        field="--marketplace",
    )

    try:
        plugin_name, target, config_path, binary_hint = install_plugin(
            source,
            codex_home,
            marketplace,
            tunnel_client_bin=args.tunnel_client_bin,
        )
    except ValueError as err:
        print(str(err), file=sys.stderr)
        return 1

    print(f"Installed {plugin_name}@{marketplace}")
    print(f"Target: {target}")
    print(f"Config: {config_path}")
    if binary_hint is not None:
        print(f"Tunnel client: {binary_hint}")
    return 0

from __future__ import annotations

import os
import shutil
from pathlib import Path

from tunnel_mcp_installer.bazel_binary import find_bazel_client_binaries

BIN_HINT_FILENAME = ".tunnel-client-bin"
BINARY_RELATIVE_PATHS = (
    Path("tunnel-client"),
    Path("tunnel-client.exe"),
    Path("bin/tunnel-client"),
    Path("bin/tunnel-client.exe"),
    Path("bazel-bin/cmd/client/client"),
    Path("bazel-bin/cmd/client/client.exe"),
    Path("bazel-bin/api/tunnel-client/cmd/client/client"),
    Path("bazel-bin/api/tunnel-client/cmd/client/client.exe"),
)


def tunnel_client_bin_hint_path(root: Path) -> Path:
    return root / BIN_HINT_FILENAME


def read_tunnel_client_bin_hint(root: Path) -> Path | None:
    hint_path = tunnel_client_bin_hint_path(root)
    if not hint_path.is_file():
        return None
    value = hint_path.read_text(encoding="utf-8").strip()
    if not value:
        return None
    return Path(value).expanduser()


def is_executable_file(path: Path) -> bool:
    return path.is_file() and os.access(path, os.X_OK)


def validate_tunnel_client_bin(path_value: str, *, field: str) -> Path:
    candidate = Path(path_value).expanduser().resolve()
    if not is_executable_file(candidate):
        raise ValueError(f"{field} is not an executable file: {candidate}")
    return candidate


def tunnel_client_bin_candidates(source: Path) -> list[Path]:
    candidates: list[Path] = []
    seen: set[str] = set()
    roots = [source, *source.parents]
    for root in roots:
        root_candidates = list(map(root.__truediv__, BINARY_RELATIVE_PATHS))
        root_candidates.extend(find_bazel_client_binaries(root))
        for candidate in root_candidates:
            key = str(candidate)
            if key not in seen:
                seen.add(key)
                candidates.append(candidate)
    return candidates


def discover_tunnel_client_bin(source: Path, explicit: str | None) -> Path | None:
    if explicit and explicit.strip():
        return validate_tunnel_client_bin(explicit.strip(), field="--tunnel-client-bin")

    env_value = os.environ.get("TUNNEL_CLIENT_BIN", "").strip()
    if env_value:
        return validate_tunnel_client_bin(env_value, field="TUNNEL_CLIENT_BIN")

    hinted = read_tunnel_client_bin_hint(source)
    if hinted is not None and is_executable_file(hinted):
        return hinted.resolve()

    for candidate in tunnel_client_bin_candidates(source):
        if is_executable_file(candidate):
            return candidate.resolve()

    for path_name in ("tunnel-client", "tunnel-client.exe"):
        discovered = shutil.which(path_name)
        if discovered:
            return Path(discovered).expanduser().resolve()
    return None

